-- Données de démonstration fictives + premier administrateur.
select id, 'valide', mt_afar, mt_afar, 'simulation', now(), 1,
  jsonb_build_array(jsonb_build_object('text', mt_afar, 'status', 'valide', 'saved_at', now(), 'reviewer_id', 'simulation')), true
from public.segments where id in ('seg_002','seg_004','seg_006','seg_010','seg_015');
